"""Find Median from Data Stream — two heaps that split the data in half.

`_low` is a max-heap (negated) of the smaller half, `_high` a min-heap of the
larger half. Keeping their sizes within one of each other puts the median at the
tops.

Time: O(log n) add, O(1) find   Space: O(n)
"""
import heapq


class MedianFinder:
    def __init__(self):
        self._low = []        # max-heap via negation
        self._high = []       # min-heap

    def addNum(self, num: int) -> None:
        heapq.heappush(self._low, -num)
        heapq.heappush(self._high, -heapq.heappop(self._low))
        if len(self._high) > len(self._low):
            heapq.heappush(self._low, -heapq.heappop(self._high))

    def findMedian(self) -> float:
        if len(self._low) > len(self._high):
            return float(-self._low[0])
        return (-self._low[0] + self._high[0]) / 2.0
